#include <iostream>

int main() {
    using std::cin;
    using std::cout;
    using std::endl;

    int number1{0};
    int number2{0};

    if (cin >> number1 >> number2) {
        if (number1 == number2)
            cout << number1 << " == " << number2 << endl;

        if (number1 != number2)
            cout << number1 << " != " << number2 << endl;

        if (number1 < number2)
            cout << number1 << " < " << number2 << endl;

        if (number1 > number2)
            cout << number1 << " > " << number2 << endl;

        if (number1 <= number2)
            cout << number1 << " <= " << number2 << endl;

        if (number1 >= number2)
            cout << number1 << " >= " << number2 << endl;
    }

    return 0;
}

#include <iostream>

int main() {
    using std::cout;
    using std::endl;

    int a{0};
    int b{0};

    // Right-to-left associativity of assignment
    a = b = 5;
    cout << "a = " << a << ", b = " << b << endl;

    // Precedence: arithmetic (+) takes precedence over relational (<)
    // a + 2 evaluates to 7, which is < 10 -> true (1)
    bool result = a + 2 < 10;
    cout << "a + 2 < 10 is " << (result ? "true" : "false") << endl;

    // Safe if construct without misplaced semicolon
    if (a == b)
        cout << "a equals b correctly verified" << endl;

    return 0;
}

